17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the same identity (telephone, email and household) already exists";
57	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
58	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners for today has already been reached";
59	    private static final String ERROR_FUTURE_REGISTRATION_DATE = "The registration date must not be later than the current server date";
60	
61	    /**
62	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
63	     * class.
64	     *
65	     * @param e     Object referring to the thrown exception.
66	     * @param status HTTP response status.
67	     * @param url URL request.
68	     */
69	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
70	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
71	        problemDetail.setType(URI.create(url.toString()));
72	        problemDetail.setTitle(e.getClass().getSimpleName());
73	        problemDetail.setDetail(detail);
74	        problemDetail.setProperty("timestamp", Instant.now());
75	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
76	        return problemDetail;
77	    }
78	
79	    /**
80	     * Builds a 409 Conflict response for a create request that collides with an existing owner. The
81	     * body is a {@link ProblemDetail} carrying {@code detail} and an {@code errors} array naming the
82	     * conflicting fields, matching the shape produced for the other owner-creation error responses.
83	     *
84	     * @param e Object referring to the thrown exception.
85	     * @param request {@link HttpServletRequest} object referring to the current request.
86	     * @param detail the human-readable detail message.
87	     * @param errors the names of the fields whose values conflicted.
88	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
89	     */
90	    private ResponseEntity<ProblemDetail> conflict(Exception e, HttpServletRequest request, String detail, List<String> errors) {
91	        HttpStatus status = HttpStatus.CONFLICT;
92	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
93	        problemDetail.setProperty("errors", errors);
94	        return ResponseEntity.status(status).body(problemDetail);
95	    }
96	
97	    /**
98	     * Builds a 400 Bad Request response for a create request rejected on a single owner field. The body
99	     * is a {@link ProblemDetail} carrying the generic invalid-request detail and an {@code errors} array
100	     * naming the single offending {@code field}, mirroring the shape produced for Bean Validation
101	     * failures. {@code logContext} labels the rejection in the debug log.
102	     *
103	     * @param e Object referring to the thrown exception.
104	     * @param request {@link HttpServletRequest} object referring to the current request.
105	     * @param logContext a short label describing the rejection, for the debug log.
106	     * @param field the name of the single field that was rejected.
107	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
108	     */
109	    private ResponseEntity<ProblemDetail> invalidField(Exception e, HttpServletRequest request, String logContext, String field) {
110	        HttpStatus status = HttpStatus.BAD_REQUEST;
111	        logger.debug("{} at {} {}: {}", logContext, request.getMethod(), request.getRequestURI(), e.getMessage());
112	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
113	        detail.setProperty("errors", List.of(field));
114	        return ResponseEntity.status(status).body(detail);
115	    }
116	
117	    /**
118	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
119	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
120	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
121	     * would catch it and report an authorization failure as a 500.
122	     *
123	     * @param e The {@link AccessDeniedException} to propagate
124	     * @throws AccessDeniedException always
125	     */
126	    @ExceptionHandler(AccessDeniedException.class)
127	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
128	        throw e;
129	    }
130	
131	    /**
132	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
133	     *
134	     * @param e The {@link Exception} to be handled
135	     * @param request {@link HttpServletRequest} object referring to the current request.
136	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
137	     */
138	    @ExceptionHandler(Exception.class)
139	    @ResponseBody
140	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
141	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
142	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
143	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
144	        return ResponseEntity.status(status).body(detail);
145	    }
146	
147	    /**
148	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
149	     * method returns a 404 Not Found status if an entity does not exist.
150	     *
151	     * @param e The {@link DataIntegrityViolationException} to be handled
152	     * @param request {@link HttpServletRequest} object referring to the current request.
153	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
154	     */
155	    @ExceptionHandler(DataIntegrityViolationException.class)
156	    @ResponseBody
157	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
158	        logger.warn("Data integrity violation at {} {}: {}",
159	            request.getMethod(),
160	            request.getRequestURI(),
161	            e.getMessage());
162	        logger.debug("Data integrity violation stacktrace", e);
163	        HttpStatus status = HttpStatus.NOT_FOUND;
164	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
165	        return ResponseEntity.status(status).body(detail);
166	    }
167	
168	    /**
169	     * Handles exception thrown by Bean Validation on controller methods parameters
170	     *
171	     * @param e The {@link MethodArgumentNotValidException} to be handled
172	     * @param request {@link HttpServletRequest} object referring to the current request.
173	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
174	     */
175	    @ExceptionHandler(MethodArgumentNotValidException.class)
176	    @ResponseBody
177	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
178	        HttpStatus status = HttpStatus.BAD_REQUEST;
179	        BindingErrorsResponse errors = new BindingErrorsResponse();
180	        BindingResult bindingResult = e.getBindingResult();
181	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
182	        if (bindingResult.hasErrors()) {
183	            errors.addAllErrors(bindingResult);
184	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
185	                .map(FieldError::getField)
186	                .distinct()
187	                .toList();
188	            detail.setProperty("errors", invalidFields);
189	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
190	                .map(fieldError -> {
191	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
192	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
193	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
194	                        fieldError.getField(),
195	                        defaultMessage,
196	                        rejectedValue);
197	                    return new ValidationMessageDto(message)
198	                        .putAdditionalProperty("field", fieldError.getField())
199	                        .putAdditionalProperty("rejectedValue", rejectedValue)
200	                        .putAdditionalProperty("defaultMessage", defaultMessage);
201	                })
202	                .toList();
203	            logger.debug("Validation error at {} {}: {}",
204	                request.getMethod(),
205	                request.getRequestURI(),
206	                bindingResult.getFieldErrors());
207	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
208	            return ResponseEntity.status(status).body(detail);
209	        }
210	        return ResponseEntity.status(status).body(detail);
211	    }
212	
213	    /**
214	     * Handles {@link InvalidOwnerFieldsException} raised when an owner has required fields that are
215	     * present but blank (whitespace-only). Returns a 400 Bad Request whose body carries an
216	     * {@code errors} array listing the name of each blank field, mirroring the shape produced for
217	     * Bean Validation failures.
218	     *
219	     * @param e The {@link InvalidOwnerFieldsException} to be handled
220	     * @param request {@link HttpServletRequest} object referring to the current request.
221	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
222	     */
223	    @ExceptionHandler(InvalidOwnerFieldsException.class)
224	    @ResponseBody
225	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
226	        HttpStatus status = HttpStatus.BAD_REQUEST;
227	        logger.debug("Blank owner fields at {} {}: {}",
228	            request.getMethod(),
229	            request.getRequestURI(),
230	            e.getFields());
231	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
232	        detail.setProperty("errors", e.getFields());
233	        return ResponseEntity.status(status).body(detail);
234	    }
235	
236	    /**
237	     * Handles {@link InvalidOwnerPostcodeException} raised when an owner submitted to the create
238	     * endpoint carries a well-formed 4-digit {@code postcode} that is out of range for the owner's
239	     * city region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). Returns a 400 Bad Request whose body
240	     * carries an {@code errors} array naming the {@code postcode} field, mirroring the shape produced
241	     * for Bean Validation failures.
242	     *
243	     * @param e The {@link InvalidOwnerPostcodeException} to be handled
244	     * @param request {@link HttpServletRequest} object referring to the current request.
245	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
246	     */
247	    @ExceptionHandler(InvalidOwnerPostcodeException.class)
248	    @ResponseBody
249	    public ResponseEntity<ProblemDetail> handleInvalidOwnerPostcodeException(InvalidOwnerPostcodeException e, HttpServletRequest request) {
250	        return this.invalidField(e, request, "Invalid owner postcode", "postcode");
251	    }
252	
253	    /**
254	     * Handles {@link DisposableEmailDomainException} raised when an owner submitted to the create
255	     * endpoint carries an {@code email} whose domain is on the disposable-domain blocklist
256	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Returns a 400 Bad
257	     * Request whose body carries an {@code errors} array naming the {@code email} field, mirroring
258	     * the shape produced for Bean Validation failures.
259	     *
260	     * @param e The {@link DisposableEmailDomainException} to be handled
261	     * @param request {@link HttpServletRequest} object referring to the current request.
262	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
263	     */
264	    @ExceptionHandler(DisposableEmailDomainException.class)
265	    @ResponseBody
266	    public ResponseEntity<ProblemDetail> handleDisposableEmailDomainException(DisposableEmailDomainException e, HttpServletRequest request) {
267	        return this.invalidField(e, request, "Disposable owner email domain", "email");
268	    }
269	
270	    /**
271	     * Handles {@link DuplicateOwnerIdentityException} raised when an owner submitted to the create
272	     * endpoint has a derived identity key (normalized telephone, email and household id) that exactly
273	     * equals an existing owner's. This single key consolidates the former separate telephone, email
274	     * and household duplicate checks. Returns a 409 Conflict.
275	     *
276	     * @param e The {@link DuplicateOwnerIdentityException} to be handled
277	     * @param request {@link HttpServletRequest} object referring to the current request.
278	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
279	     */
280	    @ExceptionHandler(DuplicateOwnerIdentityException.class)
281	    @ResponseBody
282	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerIdentityException(DuplicateOwnerIdentityException e, HttpServletRequest request) {
283	        logger.debug("Duplicate owner identity at {} {}: {}",
284	            request.getMethod(),
285	            request.getRequestURI(),
286	            e.getIdentityKey());
287	        return this.conflict(e, request, ERROR_DUPLICATE_IDENTITY, List.of("identityKey"));
288	    }
289	
290	    /**
291	     * Handles {@link OwnerCityAtCapacityException} raised when an owner submitted to the create
292	     * endpoint would be placed in a city that already contains the maximum number of owners (50 or
293	     * more). Returns a 409 Conflict.
294	     *
295	     * @param e The {@link OwnerCityAtCapacityException} to be handled
296	     * @param request {@link HttpServletRequest} object referring to the current request.
297	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
298	     */
299	    @ExceptionHandler(OwnerCityAtCapacityException.class)
300	    @ResponseBody
301	    public ResponseEntity<ProblemDetail> handleOwnerCityAtCapacityException(OwnerCityAtCapacityException e, HttpServletRequest request) {
302	        logger.debug("Owner city at capacity at {} {}: {}",
303	            request.getMethod(),
304	            request.getRequestURI(),
305	            e.getCity());
306	        return this.conflict(e, request, ERROR_CITY_AT_CAPACITY, List.of("city"));
307	    }
308	
309	    /**
310	     * Handles {@link DailyOwnerRegistrationLimitException} raised when an owner submitted to the
311	     * create endpoint would exceed the maximum number of owners that may be registered on a single
312	     * day (100 or more owners already carry today's {@code registrationDate}). Returns a
313	     * 429 Too Many Requests whose body carries an {@code errors} array naming the
314	     * {@code registrationDate} field, matching the shape produced for the other owner-creation error
315	     * responses.
316	     *
317	     * @param e The {@link DailyOwnerRegistrationLimitException} to be handled
318	     * @param request {@link HttpServletRequest} object referring to the current request.
319	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
320	     */
321	    @ExceptionHandler(DailyOwnerRegistrationLimitException.class)
322	    @ResponseBody
323	    public ResponseEntity<ProblemDetail> handleDailyOwnerRegistrationLimitException(DailyOwnerRegistrationLimitException e, HttpServletRequest request) {
324	        logger.debug("Daily owner registration limit reached at {} {}: {}",
325	            request.getMethod(),
326	            request.getRequestURI(),
327	            e.getDate());
328	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
329	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT);
330	        detail.setProperty("errors", List.of("registrationDate"));
331	        return ResponseEntity.status(status).body(detail);
332	    }
333	
334	    /**
335	     * Handles {@link FutureRegistrationDateException} raised when an owner submitted to the create
336	     * endpoint carries a {@code registrationDate} that is later than the server's current date.
337	     * Returns a 400 Bad Request whose body carries an {@code errors} array naming the
338	     * {@code registrationDate} field, mirroring the shape produced for the other owner-creation
339	     * error responses.
340	     *
341	     * @param e The {@link FutureRegistrationDateException} to be handled
342	     * @param request {@link HttpServletRequest} object referring to the current request.
343	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
344	     */
345	    @ExceptionHandler(FutureRegistrationDateException.class)
346	    @ResponseBody
347	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
348	        HttpStatus status = HttpStatus.BAD_REQUEST;
349	        logger.debug("Future registration date at {} {}: {}",
350	            request.getMethod(),
351	            request.getRequestURI(),
352	            e.getRegistrationDate());
353	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_FUTURE_REGISTRATION_DATE);
354	        detail.setProperty("errors", List.of("registrationDate"));
355	        return ResponseEntity.status(status).body(detail);
356	    }
357	
358	}
